import fs from "fs";
import path from "path";
import { SVIFile } from "./types";
import { LLMProcessor } from "../llm/llm";
import { SviConfig } from "../config/config";
import { extractDeclarationsPromptTemplate } from "./prompts/extractDeclarations";
import CacheManager from "../svi/cacheManager";
import logger from "../utils/logger";
import { getRelativePath } from "../utils/file";

// Generated file path: src\svi\sviDependencies.ts
export default class SviDependencies {
  private llmProcessor: LLMProcessor;
  private config: SviConfig;
  private isPreliminary: boolean;

  private dependenciesDeclarations: { relativePath: string; content: string; source: 'llm' | 'cache' }[] = [];
  private llmGeneratedFiles: string[] = [];
  private cacheUsedFiles: string[] = [];

  constructor(llmProcessor: LLMProcessor, config: SviConfig, isPreliminary: boolean) {
    this.llmProcessor = llmProcessor;
    this.config = config;
    this.isPreliminary = isPreliminary;
  }

  public async loadDependenciesDeclarations(sviFile: SVIFile): Promise<boolean> {
    logger.trace(`Starting to load dependencies for SVI file: '${sviFile.getSviFileName()}'`);
    // Clear previous declarations for a fresh load
    this.dependenciesDeclarations = [];
    this.llmGeneratedFiles = [];
    this.cacheUsedFiles = [];

    const sviFileDirectory = sviFile.getSviFileDirectory();
    const dependencies = sviFile.dependencies || [];

    let hasError = false;

    for (const dependencyFilename of dependencies) {
      const dependencyFullPath = path.resolve(sviFileDirectory, dependencyFilename);
      const relativeDependencyPath = getRelativePath(dependencyFullPath, this.config.configDir);
      logger.trace(`Processing dependency: '${dependencyFilename}' (Resolved to: '${dependencyFullPath}')`);

      if (!fs.existsSync(dependencyFullPath)) {
        if (this.isPreliminary) {
          logger.trace(`Skipping non-existent dependency file in preliminary run: '${dependencyFullPath}'`);
          continue;
        } else {
          logger.error(
            `File '${sviFile.getSviFileName()}' from 'Dependencies' section not found at path: '${dependencyFullPath}'.`
          );
          hasError = true;
          continue; // Continue to check other dependencies, but flag an error for final return
        }
      }

      const cacheManager = new CacheManager(path.dirname(dependencyFullPath));
      let declarationsContent: string | null = null;
      let declarationSource: 'llm' | 'cache' = 'llm'; // Default to LLM, will be updated if from cache

      if (cacheManager.isFileExportsCacheValid(dependencyFullPath)) {
        declarationsContent = cacheManager.getFileExportsFromCache(dependencyFullPath);
        if (declarationsContent) {
          declarationSource = 'cache';
          this.cacheUsedFiles.push(relativeDependencyPath);
          logger.trace(`Declarations for '${relativeDependencyPath}' loaded from cache.`);
        } else {
          // Cache was valid but content was null (e.g., empty cache file), proceed to LLM
          logger.trace(`Cache valid for '${relativeDependencyPath}' but content empty. Proceeding to LLM.`);
          declarationsContent = null; // Ensure it's null to trigger LLM path below
        }
      }

      if (!declarationsContent) {
        // If not from cache, or cache was empty, ask LLM
        logger.info(`LLM will be called to generate declarations for the following file: '${relativeDependencyPath}'`);
        try {
          const sourceCode = fs.readFileSync(dependencyFullPath, 'utf-8');
          const programmingLanguagePhrase = this.config.programmingLanguage
            ? `programming language ${this.config.programmingLanguage}`
            : '';

          const prompt = extractDeclarationsPromptTemplate
            .replace('{{programmingLanguage}}', programmingLanguagePhrase)
            .replace('{{sourceCode}}', sourceCode);

          const promptDescription = `Declarations extraction from ${relativeDependencyPath}`;

          const llmResult = await this.llmProcessor.ask(prompt, undefined, promptDescription);

          if (!llmResult) {
            logger.error(`LLM returned no declarations for file: '${relativeDependencyPath}'.`);
            hasError = true;
            continue; // Continue to check other dependencies, but flag an error
          }
          declarationsContent = llmResult;
          declarationSource = 'llm';
          this.llmGeneratedFiles.push(relativeDependencyPath);
          cacheManager.updateFileExportsInCache(dependencyFullPath, declarationsContent);
          logger.trace(`Declarations for '${relativeDependencyPath}' generated by LLM and cached.`);

        } catch (error: any) {
          logger.error(`Error processing dependency '${relativeDependencyPath}' with LLM: ${error.message}`);
          hasError = true;
          continue; // Continue on error
        }
      }

      if (declarationsContent) {
        this.dependenciesDeclarations.push({
          relativePath: relativeDependencyPath,
          content: declarationsContent,
          source: declarationSource,
        });
      }
    }

    if (hasError && !this.isPreliminary) {
      logger.info(`Dependencies declarations retrieval completed with errors for '${sviFile.getSviFileName()}'.`);
      return false;
    } else {
      logger.info(`Dependencies declarations retrieved for '${sviFile.getSviFileName()}'.`);
      if (this.llmGeneratedFiles.length > 0) {
        logger.info(`  Generated by LLM: ${this.llmGeneratedFiles.join(', ')}`);
      }
      if (this.cacheUsedFiles.length > 0) {
        logger.info(`  From cache: ${this.cacheUsedFiles.join(', ')}`);
      }
      return true;
    }
  }

  public getDependenciesDeclarationsAsString(): string {
    if (this.dependenciesDeclarations.length === 0) {
      return '';
    }

    const declarationStrings = this.dependenciesDeclarations.map(dep => {
      // Format: "Declarations from file: <path>\n\n<content>\n"
      return `Declarations from file: ${dep.relativePath}\n\n${dep.content}\n`;
    });

    // Join with an empty line between each block, resulting in the format:
    // Block1\n
    // \n
    // Block2\n
    // Which means:
    // Header1
    //
    // Content1
    //
    // Header2
    //
    // Content2
    return declarationStrings.join('\n');
  }
}